/// Created for the task - CB799.
/// </summary>
[DataContract]
public class METDutyRollMonthlyBusinessEventsContract extends BusinessEventsContract
{
    str         sites;
    const str   delimeter = ', ';


}

Method.Source:
/// <summary>
/// Site
/// </summary>
/// <param name = "_sites">List of Sites</param>
/// <returns>List of sites</returns>
[DataMember('Sites'), BusinessEventsDataMember("@SYS103211")]
public str parmSite(str _sites = sites)
{
    sites = _sites;
    return sites;
}

    /// <summary>
    /// Call the initialize method.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <param name = "_delimeter">str</param>
    /// <returns>METDutyRollMonthlyBusinessEventsContract</returns>
    public METDutyRollMonthlyBusinessEventsContract initialize(METDutyRollMonthlyContract _contract, str _delimeter = ',')
    {
        METDutyRollMonthlyBusinessEventsContract contract = new METDutyRollMonthlyBusinessEventsContract();

        sites = this.getSites(_contract, _delimeter);

        return contract;
    }

    /// <summary>
    /// Call the initialize method.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <returns>METDutyRollMonthlyBusinessEventsContract</returns>
    public static METDutyRollMonthlyBusinessEventsContract sendEvent(METDutyRollMonthlyContract _contract)
    {
        METDutyRollMonthlyBusinessEventsContract contract = new METDutyRollMonthlyBusinessEventsContract();
        contract.initialize(_contract, delimeter);

        return contract;
    }

    /// <summary>
    /// Get the list of sites selected on the parameter.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <param name = "_delimeter">str</param>
    /// <returns>sites</returns>
    public str getSites(METDutyRollMonthlyContract _contract, str _delimeter)
    {
        ListIterator siteListIterator = new ListIterator(_contract.parmSiteList());
            
        while (siteListIterator.more())
        {
            sites += siteListIterator.value();

            siteListIterator.next();

            if (siteListIterator.more())
            {
                sites += _delimeter;
            }
        }
        return sites;
    }
